import {convertToModelMessages, createUIMessageStreamResponse} from 'ai';
import {missingKey} from '@/lib/agent/errors';
import {languageModel, parseCredential} from '@/lib/agent/model';
import {MODELS} from '@/lib/agent/models';
import {runAgent} from '@/lib/agent/run';
import type {AgentMessage} from '@/lib/agent/types';
import {getServerCredential} from '@/lib/auth/server';
import type {Project} from '@/lib/sandbox/project';
import {openProject, sandboxConfigured} from '@/lib/sandbox/sandbox';

export async function POST(req: Request) {
  const body: {messages: AgentMessage[]; model: string; credential: unknown; sandboxId?: string | null} = await req.json();
  const model = MODELS.find(m => m.id === body.model);
  if (!model) return new Response(`${body.model} is not connected yet.`, {status: 400});
  const bodyCredential = parseCredential(body.credential);
  const credential = bodyCredential?.provider === model.provider ? bodyCredential : model.provider === 'openai' ? await getServerCredential(req) : null;
  if (!credential) return new Response(missingKey(model), {status: 401});

  let project: Project | undefined;
  if (body.sandboxId && sandboxConfigured()) {
    try {
      project = await openProject(body.sandboxId);
    } catch {
      return new Response('The preview sandbox is not reachable. Reload to try again.', {status: 503});
    }
  }

  const {stream} = runAgent({
    model: languageModel(body.model, credential),
    messages: await convertToModelMessages(body.messages),
    project,
    abortSignal: req.signal,
  });
  return createUIMessageStreamResponse({stream});
}
import {logEvent, parseKeepEvent} from '@/lib/agent/events';

export async function POST(req: Request) {
  const event = parseKeepEvent(await req.json());
  if (!event) return new Response('Only keep events are accepted here.', {status: 400});
  logEvent(event);
  return new Response(null, {status: 204});
}
import {restoreCheckpoint} from '@/lib/agent/checkpoint';
import {logEvent} from '@/lib/agent/events';
import {openProject, sandboxConfigured} from '@/lib/sandbox/sandbox';

export async function POST(req: Request) {
  const body: {sandboxId?: unknown; checkpointId?: unknown; turnId?: unknown; traceId?: unknown} = await req.json();
  const {sandboxId, checkpointId, turnId, traceId} = body;
  if (typeof sandboxId !== 'string' || typeof checkpointId !== 'string' || typeof turnId !== 'string') {
    return new Response('Restore needs a sandbox, a checkpoint and a turn.', {status: 400});
  }
  if (!sandboxConfigured()) return new Response('The preview sandbox is not configured yet.', {status: 503});
  try {
    const headId = await restoreCheckpoint(await openProject(sandboxId), checkpointId);
    logEvent({type: 'restore', turnId, traceId: typeof traceId === 'string' ? traceId : undefined, checkpointId, at: new Date().toISOString()});
    return Response.json({headId});
  } catch (error) {
    console.error('[restore] failed:', error instanceof Error ? error.message : 'unknown');
    return new Response('That checkpoint could not be restored. Reload to try again.', {status: 502});
  }
}
import {connectSandbox, createSandbox, sandboxConfigured} from '@/lib/sandbox/sandbox';

export async function POST(req: Request) {
  if (!sandboxConfigured()) return new Response('The preview sandbox is not configured yet.', {status: 503});
  const {sandboxId}: {sandboxId?: string | null} = await req.json();
  try {
    if (sandboxId) return Response.json(await connectSandbox(sandboxId).catch(() => createSandbox()));
    return Response.json(await createSandbox());
  } catch (error) {
    console.error('[sandbox] start failed:', error instanceof Error ? error.message : 'unknown');
    return new Response('The preview sandbox could not start. Reload to try again.', {status: 502});
  }
}
