      contentPadding={0}
      topNav={
        <TopNav
          label="Workspace"
          heading={PROJECT_NAME}
          endContent={
            <HStack gap={2} align="center">
              <ModelPicker value={model} onChange={setModel} />
              <AuthControls />
            </HStack>
          }
