import 'server-only';
import {drizzle, type PostgresJsDatabase} from 'drizzle-orm/postgres-js';
import postgres from 'postgres';
import * as schema from './schema';

const globalDb = globalThis as typeof globalThis & {betterlookDb?: PostgresJsDatabase<typeof schema>};
let db: PostgresJsDatabase<typeof schema> | undefined;

export function getDb() {
  const cached = db ?? globalDb.betterlookDb;
  if (cached) return cached;

  const url = process.env.DATABASE_URL;
  if (!url) throw new Error('DATABASE_URL is required.');

  db = drizzle(postgres(url, {prepare: false, ssl: 'verify-full'}), {schema});
  if (process.env.NODE_ENV === 'development') globalDb.betterlookDb = db;
  return db;
}

import {defineConfig} from 'drizzle-kit';

const url = process.env.DIRECT_URL;

export default defineConfig({
  dialect: 'postgresql',
  schema: './src/lib/db/schema.ts',
  out: '../../supabase/migrations',
  schemaFilter: ['public'],
  entities: {roles: {provider: 'supabase'}},
  dbCredentials: url ? {url} : undefined,
});

import {bigint, index, jsonb, pgEnum, pgTable, text, timestamp, uuid} from 'drizzle-orm/pg-core';
import {authUsers} from 'drizzle-orm/supabase';
import type {AgentMessage, AgentMetadata, Usage} from '@/lib/agent/types';

export const users = pgTable('users', {
  id: uuid('id').primaryKey().references(() => authUsers.id, {onDelete: 'cascade'}),
  createdAt: timestamp('created_at', {withTimezone: true}).defaultNow().notNull(),
}).enableRLS();

export const projects = pgTable('projects', {
  id: uuid('id').defaultRandom().primaryKey(),
  ownerId: uuid('owner_id').notNull().references(() => users.id, {onDelete: 'cascade'}),
  name: text('name').notNull(),
  sandboxId: text('sandbox_id').unique(),
  createdAt: timestamp('created_at', {withTimezone: true}).defaultNow().notNull(),
  updatedAt: timestamp('updated_at', {withTimezone: true}).defaultNow().notNull(),
}, table => [index('projects_owner_id_idx').on(table.ownerId)]).enableRLS();

export const conversations = pgTable('conversations', {
  id: uuid('id').defaultRandom().primaryKey(),
  projectId: uuid('project_id').notNull().references(() => projects.id, {onDelete: 'cascade'}),
  createdAt: timestamp('created_at', {withTimezone: true}).defaultNow().notNull(),
  updatedAt: timestamp('updated_at', {withTimezone: true}).defaultNow().notNull(),
}, table => [index('conversations_project_id_idx').on(table.projectId)]).enableRLS();

export const messageRole = pgEnum('message_role', ['user', 'assistant', 'system']);

export const messages = pgTable('messages', {
  id: bigint('id', {mode: 'bigint'}).generatedAlwaysAsIdentity().primaryKey(),
  conversationId: uuid('conversation_id').notNull().references(() => conversations.id, {onDelete: 'cascade'}),
  role: messageRole('role').notNull(),
  parts: jsonb('parts').$type<AgentMessage['parts']>().notNull(),
  metadata: jsonb('metadata').$type<Pick<AgentMetadata, 'model' | 'notice'>>(),
  usage: jsonb('usage').$type<Usage>(),
  createdAt: timestamp('created_at', {withTimezone: true}).defaultNow().notNull(),
}, table => [index('messages_conversation_id_id_idx').on(table.conversationId, table.id)]).enableRLS();

export const eventType = pgEnum('event_type', ['restore', 'keep', 'approve', 'deny']);

export const events = pgTable('events', {
  id: bigint('id', {mode: 'bigint'}).generatedAlwaysAsIdentity().primaryKey(),
  type: eventType('type').notNull(),
  reason: text('reason').notNull(),
  toolCallId: text('tool_call_id'),
  createdAt: timestamp('created_at', {withTimezone: true}).defaultNow().notNull(),
}).enableRLS();

import 'server-only';

export function getSupabaseSecretKey() {
  const key = process.env.SUPABASE_SECRET_KEY;
  if (!key) throw new Error('SUPABASE_SECRET_KEY is required.');
  return key;
}

