  return ['SELF_SIGNED_CERT_IN_CHAIN', 'UNABLE_TO_VERIFY_LEAF_SIGNATURE', 'ERR_TLS_CERT_ALTNAME_INVALID', 'CONNECT_TIMEOUT', 'ENOTFOUND', 'ECONNREFUSED', '28P01'].includes(error?.code) ? error.code : 'unclassified';
