store("db_final_audit", `env -i PATH="$PATH" node --env-file=.env --input-type=module - 2>/dev/null <<'JS'
import {createHash} from 'node:crypto';
import {readFileSync} from 'node:fs';
import postgres from 'postgres';
import {verifiedDatabaseUrl} from './src/lib/db/tls.ts';

const expected = ['conversations', 'messages', 'projects', 'users'];
const migration = readFileSync('../../supabase/migrations/0000_product_tables.sql');
const hash = createHash('sha256').update(migration).digest('hex');
const sql = postgres(verifiedDatabaseUrl('DIRECT_URL'), {max: 1, connect_timeout: 10});
let stage = 'migration ledger';

try {
  const [ledger] = await sql\`select count(*)::int as entries, count(*) filter (where hash = \${hash})::int as matches
    from drizzle.__drizzle_migrations\`;
  console.log('drizzle.__drizzle_migrations | entries=' + ledger.entries + ' | 0000 hash matches=' + ledger.matches);
  if (ledger.entries !== 1 || ledger.matches !== 1) throw new Error();

  stage = 'catalog';
  const tables = await sql\`select
    c.table_name, pc.relrowsecurity,
    (select count(*)::int from pg_catalog.pg_policy p where p.polrelid = pc.oid) as policies,
    (pc.relowner = anon.oid or anon.rolbypassrls or anon.rolsuper) as anon_bypasses_rls,
    string_agg(c.column_name || ' ' || (case when c.data_type = 'USER-DEFINED' then c.udt_name else c.data_type end)
      || case when c.is_nullable = 'YES' then ' NULL' else ' NOT NULL' end, ', ' order by c.ordinal_position) as columns
  from information_schema.columns c
  join pg_catalog.pg_namespace ns on ns.nspname = c.table_schema
  join pg_catalog.pg_class pc on pc.relnamespace = ns.oid and pc.relname = c.table_name and pc.relkind in ('r', 'p')
  cross join (select oid, rolbypassrls, rolsuper from pg_catalog.pg_roles where rolname = 'anon') anon
  where c.table_schema = 'public'
  group by c.table_name, pc.oid, pc.relrowsecurity, pc.relowner, anon.oid, anon.rolbypassrls, anon.rolsuper
  order by c.table_name\`;
  if (tables.map(row => row.table_name).join(',') !== expected.join(',')) throw new Error();
  for (const row of tables) {
    console.log(row.table_name + ' | ' + row.columns + ' | relrowsecurity=' + row.relrowsecurity +
      ' | policies=' + row.policies + ' | anon_bypasses_rls=' + row.anon_bypasses_rls);
    if (!row.relrowsecurity || row.policies !== 0 || row.anon_bypasses_rls) throw new Error();
  }

  stage = 'message identity constraint';
  const [unique] = await sql\`select pg_catalog.pg_get_constraintdef(c.oid) as definition
    from pg_catalog.pg_constraint c
    where c.conrelid = 'public.messages'::regclass
      and c.conname = 'messages_conversation_id_ui_id_unique' and c.contype = 'u'\`;
  if (unique?.definition !== 'UNIQUE (conversation_id, ui_id)') throw new Error();
  console.log('messages | ' + unique.definition);
  if (!tables.find(row => row.table_name === 'messages').columns.includes('ui_id text NOT NULL')) throw new Error();

  stage = 'public REST';
  const base = new URL(process.env.NEXT_PUBLIC_SUPABASE_URL);
  const key = process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY;
  if (base.protocol !== 'https:' || !key?.startsWith('sb_publishable_')) throw new Error();
  for (const table of expected) {
    const endpoint = new URL('/rest/v1/' + table, base);
    endpoint.searchParams.set('select', 'id');
    endpoint.searchParams.set('limit', '1');
    const response = await fetch(endpoint, {
      headers: {apikey: key, accept: 'application/json'},
      redirect: 'error',
      signal: AbortSignal.timeout(10000),
    });
    if (response.ok) {
      const rows = await response.json();
      if (!Array.isArray(rows) || rows.length !== 0) throw new Error();
      console.log(table + ' | REST HTTP ' + response.status + ' | []');
      continue;
    }
    if (![401, 403].includes(response.status)) {
      console.log(table + ' | REST HTTP ' + response.status + ' | unexpected response');
      throw new Error();
    }
    console.log(table + ' | REST HTTP ' + response.status + ' | access denied');
  }
} catch (error) {
  const code = ['SELF_SIGNED_CERT_IN_CHAIN', 'UNABLE_TO_VERIFY_LEAF_SIGNATURE', 'ERR_TLS_CERT_ALTNAME_INVALID',
    'CONNECT_TIMEOUT', 'ENOTFOUND', 'ECONNREFUSED', '28P01', '42P01', '42501'].includes(error?.code) ? ' (' + error.code + ')' : '';
  console.log('Verification failed during ' + stage + code + '.');
  process.exitCode = 1;
} finally {
  await sql.end({timeout: 2});
}
JS`);
const r=await Promise.allSettled([tools.write_stdin({session_id:32499,chars:"",yield_time_ms:1000,max_output_tokens:2500}),tools.write_stdin({session_id:44408,chars:"",yield_time_ms:1000,max_output_tokens:4600})]);for(const x of r)text(x);

const cmd=load("db_final_audit");
const config={cmd,workdir:"/Users/rushout/.paradev/worktrees/betterlook/db/apps/web",yield_time_ms:1000,max_output_tokens:4200};
const r=await Promise.allSettled([tools.exec_command(config),tools.exec_command(config)]);for(const x of r)text(x);

