const email = 'rls-check-db2b-' + testId + '@example.com';
const projectId = randomUUID();
const conversationId = randomUUID();
const uiId = randomUUID();
let sql;
let userId;
let mayHaveCreatedUser = false;
let stage = 'configuration';
let failed = false;

function setup(name) {
  const url = process.env[name];
  if (!url) throw new Error();
  return url;
}

function reportFailure(error) {
  const code = ['28P01', '23503', '23505', '42501', 'CONNECT_TIMEOUT', 'SELF_SIGNED_CERT_IN_CHAIN'].includes(error?.code) ? ' (' + error.code + ')' : '';
  console.log('Verification failed during ' + stage + code + '.');
  failed = true;
}

async function request(base, path, key, options = {}) {
  const headers = {apikey: key, accept: 'application/json'};
  if (options.body) headers['content-type'] = 'application/json';
  return fetch(new URL(path, base), {
    ...options, headers, redirect: 'error', signal: AbortSignal.timeout(10000),
  });
}

async function authMatches() {
  return sql`select id from auth.users where email = ${email}`;
}

async function serverCounts() {
  const [counts] = await sql`select
    (select count(*)::int from public.users where id = ${userId}) as users,
    (select count(*)::int from public.projects where id = ${projectId}) as projects,
    (select count(*)::int from public.conversations where id = ${conversationId}) as conversations,
    (select count(*)::int from public.messages where conversation_id = ${conversationId} and ui_id = ${uiId}) as messages`;
  return counts;
}

async function retryCleanup(action) {
  let error;
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      return await action();
    } catch (failure) {
      error = failure;
    }
  }
  throw error;
}

let base;
let secret;
try {
  base = new URL(setup('NEXT_PUBLIC_SUPABASE_URL'));
  secret = setup('SUPABASE_SECRET_KEY');
  const publishable = setup('NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY');
  if (base.protocol !== 'https:' || !secret.startsWith('sb_secret_') || !publishable.startsWith('sb_publishable_')) throw new Error();
