  if (!sql.options.ssl?.ca || sql.options.ssl.rejectUnauthorized === false || sql.options.ssl.checkServerIdentity) throw new Error();

  stage = 'server preflight';
  if ((await authMatches()).length !== 0) throw new Error();
  const grants = await sql`select table_name, has_table_privilege('anon', 'public.' || table_name, 'SELECT') as can_select
