  stage = 'admin user creation';
  mayHaveCreatedUser = true;
  const created = await request(base, '/auth/v1/admin/users', secret, {
    method: 'POST',
    body: JSON.stringify({email, email_confirm: true}),
  });
  if (!created.ok) {
    console.log('Admin user creation | HTTP ' + created.status);
    throw new Error();
  }
  const returned = await created.json();
  const [account] = await authMatches();
  if (!account || returned.id !== account.id) throw new Error();
  userId = account.id;
  console.log('Admin user creation | HTTP ' + created.status + ' | auth.users match=1');

  stage = 'sentinel insert transaction';
  await sql.begin(async tx => {
    await tx`insert into public.users (id) values (${userId})`;
    await tx`insert into public.projects (id, owner_id, name) values (${projectId}, ${userId}, 'RLS sentinel')`;
    await tx`insert into public.conversations (id, project_id) values (${conversationId}, ${projectId})`;
    await tx`insert into public.messages (conversation_id, ui_id, role, parts)
      values (${conversationId}, ${uiId}, 'user', '[]'::jsonb)`;
  });
  console.log('Sentinel insert | committed one transaction');

  stage = 'server visibility after commit';
  const before = await serverCounts();
  if (tables.some(table => before[table] !== 1)) throw new Error();

  for (const table of tables) {
    stage = 'publishable REST for ' + table;
    const endpoint = new URL('/rest/v1/' + table, base);
    endpoint.searchParams.set('select', 'id');
    if (table === 'messages') {
      endpoint.searchParams.set('conversation_id', 'eq.' + conversationId);
      endpoint.searchParams.set('ui_id', 'eq.' + uiId);
    } else {
      endpoint.searchParams.set('id', 'eq.' + {users: userId, projects: projectId, conversations: conversationId}[table]);
    }
    const response = await request(base, endpoint.pathname + endpoint.search, publishable);
    if (!response.ok) {
      console.log(table + ' | publishable REST HTTP ' + response.status);
      throw new Error();
    }
    const rows = await response.json();
    if (!Array.isArray(rows) || rows.length !== 0) throw new Error();
    console.log(table + ' | server count=' + before[table] + ' | publishable REST HTTP ' + response.status + ' | []');
  }

  stage = 'server visibility after REST';
  const after = await serverCounts();
  if (tables.some(table => after[table] !== 1)) throw new Error();
  console.log('Server still sees one sentinel per table after all REST requests.');
} catch (error) {
  reportFailure(error);
} finally {
  if (sql && mayHaveCreatedUser) {
    stage = 'sentinel cleanup';
    try {
      if (!userId) {
        const [account] = await retryCleanup(authMatches);
        userId = account?.id;
      }
      if (userId) {
        await retryCleanup(() => sql.begin(async tx => {
          await tx`delete from public.messages where conversation_id = ${conversationId} and ui_id = ${uiId}`;
          await tx`delete from public.conversations where id = ${conversationId} and project_id = ${projectId}`;
          await tx`delete from public.projects where id = ${projectId} and owner_id = ${userId}`;
          await tx`delete from public.users where id = ${userId}`;
        }));
        console.log('Sentinel delete | committed one transaction');
      }
    } catch (error) {
      reportFailure(error);
    }

    stage = 'admin user cleanup';
    try {
      if (userId) {
        const deleted = await retryCleanup(async () => {
          const response = await request(base, '/auth/v1/admin/users/' + encodeURIComponent(userId), secret, {method: 'DELETE'});
          if (!response.ok && response.status !== 404) throw new Error();
          return response;
        });
        console.log('Admin user delete | HTTP ' + deleted.status);
      }
      stage = 'cleanup verification';
      const remaining = userId ? await retryCleanup(serverCounts) : {};
      const remainingAuth = (await retryCleanup(authMatches)).length;
      if (Object.values(remaining).some(count => count !== 0) || remainingAuth !== 0) throw new Error();
      if (userId) console.log('Cleanup verified | users=0 | projects=0 | conversations=0 | messages=0 | auth.users=0');
      else console.log('Cleanup verified | no throwaway auth user exists');
    } catch (error) {
      reportFailure(error);
    }
  }
  await sql?.end({timeout: 2});
  if (failed) process.exitCode = 1;
}
